def developer_ids() -> set:
    """DEVELOPER_IDS; before it's set, CREATOR_ID, then OWNER_IDS (how r32 set things up), so nobody gets locked out."""
    if DEVELOPER_IDS:
        return set(DEVELOPER_IDS)
    if CREATOR_ID:
        return {CREATOR_ID}
    return set(OWNER_IDS)
