def slip_reader_on() -> bool:
    """Can the bot read screenshots at all (free scan, Gemini or Claude)?"""
    return any((r == "scan" and TESSERACT) or (r == "gemini" and GEMINI_API_KEY) or (r == "claude" and ai_enabled())
               for r in SLIP_READERS)


def free_count(how: str) -> None:
    key = f"slipreads:{datetime.now(TZ).date().isoformat()}"
    try:
        counts = json.loads(get_setting(0, key) or "{}")
    except ValueError:
        counts = {}
    counts[how] = counts.get(how, 0) + 1
    set_setting(0, key, json.dumps(counts))


def free_counts_line() -> str:
    try:
        counts = json.loads(get_setting(0, f"slipreads:{datetime.now(TZ).date().isoformat()}") or "{}")
    except ValueError:
        counts = {}
    names = {"scan": "free scan", "scan_confirm": "free scan (confirmed by hand)", "gemini": "Gemini (free)",
             "claude": "Claude", "ask_gemini": "questions on Gemini (free)", "ask_claude": "questions on Claude",
             "ask_groq": "questions on Groq (free)", "ask_cerebras": "questions on Cerebras (free)",
             "ask_openrouter": "questions on OpenRouter (free)"}
    parts = [f"{counts[k]} {names.get(k, k)}" for k in ("scan", "scan_confirm", "gemini", "claude", "ask_groq",
                                                         "ask_cerebras", "ask_openrouter", "ask_gemini", "ask_claude")
             if counts.get(k)]
    on = [names[r] if r != "scan" else "free scan" for r in SLIP_READERS
          if (r == "scan" and TESSERACT) or (r == "gemini" and GEMINI_API_KEY) or (r == "claude" and ai_enabled())]
    return (" · ".join(parts) or "none yet") + "\nReaders on, in order: " + (" → ".join(on) or "none (the form only)")


# ---- the free text scan (pure: runs in a thread, never touches the database) -------------------------

def free_prepare(raw: bytes):
    """(colour image, OCR-ready greyscale image, scale) with dark mode flipped, upscaled so small print reads."""
    from PIL import Image, ImageOps, ImageFilter, ImageStat
    img = Image.open(io.BytesIO(raw))
    sec_check_image(img)
    img.seek(0)
    img = ImageOps.exif_transpose(img).convert("RGB")
    w, h = img.size
    scale = max(1.0, min(3.0, 1600 / max(1, w)))
    if scale > 1.05:
        img = img.resize((round(w * scale), round(h * scale)), Image.LANCZOS)
    grey = img.convert("L")
    if ImageStat.Stat(grey).mean[0] < 128:          # dark mode: Tesseract wants dark text on light
        grey = ImageOps.invert(grey)
    grey = ImageOps.autocontrast(grey, cutoff=1).filter(ImageFilter.UnsharpMask(radius=1.5, percent=80, threshold=2))
    return img, grey, scale


_TESS_ENV = dict(os.environ, OMP_THREAD_LIMIT="1")     # r46: one thread per read, reads run side by side instead
FREE_BANDS = env("FREE_BANDS", "off").lower() == "on"     # r46: try reading tall shots as two bands (off: less accurate)


def _free_tess(img, psm: int, extra: Optional[list] = None, tsv: bool = True) -> str:
    buf = io.BytesIO()
    img.save(buf, "PNG")
    args = [TESSERACT, "stdin", "stdout", "--psm", str(psm), "-l", "eng"] + (extra or []) + (["tsv"] if tsv else [])
    r = subprocess.run(args, input=buf.getvalue(), capture_output=True, timeout=FREE_SCAN_TIMEOUT, env=_TESS_ENV)
    return r.stdout.decode("utf-8", "replace")


def free_split_row(grey) -> Optional[int]:
    """An empty row near the middle of a tall image (all one shade), so two halves can be read apart."""
    from PIL import ImageStat
    w, h = grey.size
    if h < 2200 or w < 200:
        return None
    best, best_sd = None, None
    for y in range(int(h * 0.42), int(h * 0.58), 3):
        sd = ImageStat.Stat(grey.crop((0, y, w, y + 3))).stddev[0]
        if best_sd is None or sd < best_sd:
            best, best_sd = y + 1, sd
            if sd < 1.0:
                break
    return best if best_sd is not None and best_sd < 6.0 else None


def _free_words_one(grey, band: int = 0, dy: int = 0) -> list[dict]:
    out = []
    for row in _free_tess(grey, 4).splitlines()[1:]:
        f = row.split("\t")
        if len(f) < 12 or f[0] != "5" or not f[11].strip():
            continue
        try:
            out.append({"text": f[11].strip(), "conf": float(f[10]), "x": int(f[6]), "y": int(f[7]) + dy, "w": int(f[8]),
                        "h": int(f[9]), "line": (band, int(f[2]), int(f[3]), int(f[4]))})
        except ValueError:
            continue
    return out


def free_words(grey) -> list[dict]:
    """Every word Tesseract saw: {text, conf, x, y, w, h, line} with line = a key shared by words on one line.
    A tall screenshot is read as two bands at the same time, split on an empty row."""
    cut = free_split_row(grey) if FREE_BANDS else None
    if cut:
        from concurrent.futures import ThreadPoolExecutor
        top, bottom = grey.crop((0, 0, grey.width, cut)), grey.crop((0, cut, grey.width, grey.height))
        with ThreadPoolExecutor(max_workers=2) as ex:
            a = ex.submit(_free_words_one, top, 0, 0)
            b = ex.submit(_free_words_one, bottom, 1, cut)
            return a.result() + b.result()
    out = []
    for row in _free_tess(grey, 4).splitlines()[1:]:
        f = row.split("\t")
        if len(f) < 12 or f[0] != "5" or not f[11].strip():
            continue
        try:
            out.append({"text": f[11].strip(), "conf": float(f[10]), "x": int(f[6]), "y": int(f[7]), "w": int(f[8]),
                        "h": int(f[9]), "line": (int(f[2]), int(f[3]), int(f[4]))})
        except ValueError:
            continue
    return out


def free_lines(words: list[dict]) -> list[dict]:
    """Words grouped into lines, top to bottom: {words, text, y, h, x0, x1}."""
    groups: dict = {}
    for wd in words:
        groups.setdefault(wd["line"], []).append(wd)
    lines = []
    for ws in groups.values():
        ws.sort(key=lambda w: w["x"])
        lines.append({"words": ws, "text": " ".join(w["text"] for w in ws), "y": min(w["y"] for w in ws),
                      "h": max(w["h"] for w in ws), "x0": min(w["x"] for w in ws),
                      "x1": max(w["x"] + w["w"] for w in ws)})
    lines.sort(key=lambda ln: (ln["y"], ln["x0"]))
    return lines


def free_reocr_number(grey, wd: dict) -> Optional[str]:
    """Read one number box again, zoomed in, digits only (fixes '495' for '49.5')."""
    from PIL import Image
    pad = max(4, wd["h"] // 3)
    box = (max(0, wd["x"] - pad), max(0, wd["y"] - pad), wd["x"] + wd["w"] + pad, wd["y"] + wd["h"] + pad)
    crop = grey.crop(box)
    crop = crop.resize((crop.width * 3, crop.height * 3), Image.LANCZOS)
    txt = _free_tess(crop, 7, ["-c", "tessedit_char_whitelist=0123456789."], tsv=False).strip()
    return txt if re.fullmatch(r"\d{1,4}(?:\.\d)?", txt) else None


def free_arrow(img, box: tuple) -> Optional[str]:
    """'over' for an up arrow, 'under' for a down arrow, from where the arrow's head (its widest part) sits."""
    x0, y0, x1, y1 = (int(v) for v in box)
    x0, y0, x1, y1 = max(0, x0), max(0, y0), min(img.width, x1), min(img.height, y1)
    if x1 - x0 < 4 or y1 - y0 < 6:
        return None
    crop = img.crop((x0, y0, x1, y1)).convert("L")
    px = crop.load()
    w, h = crop.size
    vals = sorted(px[i, j] for i in range(w) for j in range(h))
    bg = vals[len(vals) // 2]
    rows = []
    for j in range(h):
        rows.append(sum(1 for i in range(w) if abs(px[i, j] - bg) > 60))
    ink = [j for j, n in enumerate(rows) if n]
    if len(ink) < 5:
        return None
    top, bottom = ink[0], ink[-1]
    span = bottom - top + 1
    third = max(1, span // 3)
    upper = sum(rows[top:top + third])
    lower = sum(rows[bottom - third + 1:bottom + 1])
    if upper > lower * 1.25:
        return "over"
    if lower > upper * 1.25:
        return "under"
    return None


def free_green(img, wd: dict) -> float:
    """How much of a word's button is filled green (the picked More/Less on PrizePicks' builder)."""
    pad = wd["h"]
    crop = img.crop((max(0, wd["x"] - pad), max(0, wd["y"] - pad // 2), wd["x"] + wd["w"] + pad,
                     wd["y"] + wd["h"] + pad // 2))
    px = list(crop.getdata())
    green = sum(1 for r, g, b in px if g > 150 and g > r + 50 and g > b + 50)
    return green / max(1, len(px))


def free_green_side(img, top: float, bottom: float) -> Optional[str]:
    """On the builder screen the picked button is filled green: Less sits left of More."""
    w = img.width
    crop = img.crop((int(w * 0.55), max(0, int(top)), w, min(img.height, int(bottom))))
    pts = [i % crop.width for i, (r, g, b) in enumerate(crop.getdata()) if g > 150 and g > r + 50 and g > b + 50]
    if len(pts) < 50:
        return None
    centre = (sum(pts) / len(pts) + w * 0.55) / w
    return "over" if centre > 0.78 else "under"


def _free_numtext(t: str) -> str:
    """'«12.5' -> '12.5', '49,5' -> '49.5' (icons and punctuation OCR glues onto a number)."""
    if re.search(r"[#:$%/x]|\d[a-wyz]", t, re.I):   # jersey numbers, times, money, '37.5x', '6pm'
        return ""
    if "½" in t:
        t = re.sub(r"(\d*)½", lambda m: (m.group(1) or "0") + ".5", t)       # r46: "1½" is 1.5, "½" is 0.5
    core = re.sub(r"^[^\d]+|[^\d]+$", "", t).replace(",", ".")
    lead = re.match(r"^[^\d]*", t).group(0)
    if lead[-1:] in (".", ",") and lead[-2:-1] in ("", "O", "o", "D", "Q"):
        core = "0." + core                     # "O.5" / ".5" is 0.5
    return core


def _free_stat_in(text: str) -> Optional[tuple[str, int]]:
    """(stat name, where it starts) for the stat printed in this line, if any."""
    for name, rx in _FREE_STAT_RX:
        m = rx.search(text)
        if m:
            return name, m.start()
    return None


def _free_name(line: dict, max_x: Optional[float] = None, single: bool = False) -> Optional[str]:
    """A player's name at the start of a line (skipping OCR noise from photos and icons). `single` lets in a one-word
    gamer tag ('Aegis'), for esports stats."""
    text = " ".join(t for t in line["text"].split() if not ("@" in t and (free_pill_num(t)
                                                                           or not re.search(r"@\s?[A-Z]{2,4}", t))))
    if re.search(r"vs\b|\d{1,2}:\d{2}|@|\$\s?\d|#\s?\d", text, re.I) or re.search(
            r"\b(defender|midfielder|attacker|forward|goalkeeper|guard|center|qb|rb|wr|te|lw|rw|sp|rp)\b", line["text"], re.I):
        return None                            # a game header, an amount, or a team/position/jersey line
    toks = [w["text"].strip(",;:|()[]{}©@&*") for w in line["words"] if not ("@" in w["text"] and free_pill_num(w["text"]))
            and (max_x is None or w["x"] < max_x)]
    toks = ["I" + t[1:] if re.match(r"^l[^aeiouy\W\d]", t) else t for t in toks]   # "lriafen" is "Iriafen"
    if single:
        if re.search(r"[•·«»+\-]\s*[-»·•]?\s*G\b", line["text"]):
            return None                        # "Natus Vincere • G": the team and role line, not the gamer
        cm = re.search(r"(?<![\w])([A-Za-z][\w.\-]{1,15}(?:\s*\+\s*[A-Za-z][\w.\-]{1,15}){1,3})(?![\w])",
                       " ".join(toks))
        if cm:
            parts = [x.strip() for x in cm.group(1).split("+")]
            if len(parts) >= 2 and not any(x.lower() in _FREE_JUNK or _free_stat_in(x) or len(x) < 3 for x in parts):
                return " + ".join(parts)          # a combo pick: "Fuuu + Morttheus", "PerfecT + Cuzz + Bdd"
    best: list[str] = []
    run: list[str] = []
    for t in toks + [""]:
        ok = bool(t) and _FREE_NAME_TOKEN.match(t) and t.lower() not in _FREE_JUNK and not any(c.isdigit() for c in t)
        if ok:
            run.append(t)
            continue
        while run and len(run[-1]) <= 2 and run[-1] not in ("Jr", "Sr", "II", "IV") and len(run) > 1:
            run.pop()                          # trailing icon noise like "Vv"
        while len(run) > 2 and len(run[0]) <= 2 and not run[0].isupper():
            run.pop(0)                         # leading noise like "Ps" (but "OG Anunoby", "AJ Brown" stay)
        while len(run) > 2 and len(run[0]) == 1:
            run.pop(0)                         # a lone letter from the photo: "A Shohei Ohtani"
        if len(run) >= 4 and len(run[0]) <= 3 and not run[0].isupper() and run[-1] in ("Jr", "Sr", "II", "III", "IV"):
            run.pop(0)                         # "Aan James Cook III": the scrap before a full name with a suffix
        if len(run) >= 2 and sum(len(x) for x in run) > len(" ".join(best).replace(" ", "")):
            best = run[:]
        run = []
    if single and len(best) <= 1:
        if re.search(r"vs|final|\d{1,2}:\d{2}", line["text"], re.I):
            return None                        # the game header ("LGDvsJDG Final"), not a gamer tag
        tags = [t for t in toks if re.fullmatch(r"[A-Za-z][A-Za-z0-9_.\-]{2,15}", t) and t.lower() not in _FREE_JUNK
                and (not t.isupper() or (len(t) >= 4 and t.lower() not in TEAM_ABBRS)) and not _free_stat_in(t)]
        return tags[0] if tags else None
    if len(best) < 2 or len(best) > 4:
        return None
    if all(x.isupper() for x in best):        # "DAL QB", "TB RB": team and position, not a name
        return None
    if _free_stat_in(" ".join(best)):         # "Pass Yards" is a stat, not a person
        return None
    return " ".join(best)


_FREE_PILL = re.compile(r"^[^\w]*[vVtTrRlI1↑↓]?([0-9oOsS]{1,2}(?:[.,][0-9oOsS])?)$")


def free_pill_num(text: str) -> Optional[str]:
    """A number from the pick's box with the over/under arrow glued on: '@r15' -> '15', '@vos' -> '05'."""
    t = _free_numtext(text)
    if t:
        return t
    m = _FREE_PILL.match(text or "")
    if not m or not re.search(r"[sS5]", m.group(1)):
        return None
    return m.group(1).translate(str.maketrans("oOsS,", "0055."))


def free_parse(words: list[dict], img, grey) -> Optional[dict]:
    """A slip from the scan's words, in the same shape the AI readers return, plus '_unsure' with the reasons
    when anything didn't read cleanly. None when it doesn't look like a slip at all."""
    lines = free_lines(words)
    if not lines:
        return None
    full = "\n".join(ln["text"] for ln in lines)
    low = full.lower()
    unsure: list[str] = []
    # platform and entry type
    platform = None
    if "prizepicks" in low or re.search(r"\b(power|flex) play\b", low) or re.search(r"\bless\b.*\bmore\b", low):
        platform = "PrizePicks"
    elif "underdog" in low or re.search(r"\bhigher\b|\blower\b", low):
        platform = "Underdog"
    for book in ("FanDuel", "DraftKings", "BetMGM", "Caesars", "Fanatics", "bet365", "ESPN BET", "Hard Rock",
                 "BetRivers", "Kalshi", "Sleeper", "Dabble", "Betr", "ParlayPlay"):
        if book.lower() in low:
            platform = book
            break
    has_flex, has_power = bool(re.search(r"\bflex\b|\binsured\b", low)), bool(re.search(r"\bpower\b|\bstandard\b", low))
    entry_type = None if has_flex and has_power else ("flex" if has_flex else ("power" if has_power else None))
    m = re.search(r"(\d{1,2})\s*-?\s*pick", low)
    want = int(m.group(1)) if m and 2 <= int(m.group(1)) <= 12 else None
    # amounts: "$25 to win $450" / "Entry fee ... To Win ... $15 $562.50"
    cost = payout = None
    status, returned = "open", None
    m = re.search(_FREE_MONEY + r"\s*(to\s*(?:win|pay)|for|paid|won)\s*[$S]\s?([\d,]+(?:\.\d{1,2})?)(?![\d,])",
                  full, re.I)
    if m:
        cost, payout = as_amount(m.group(1)), as_amount(m.group(3))
        if m.group(2).lower() in ("paid", "won") and payout:
            status, returned = "win", payout
    else:
        for k, ln in enumerate(lines):
            if re.search(r"entry\s*fee|wager|stake", ln["text"], re.I):
                amounts = re.findall(_FREE_MONEY + r"|(?<![\d.])(\d+\.\d{2})(?!\d)",
                                     " ".join(x["text"] for x in lines[k:k + 3]))
                vals = [as_amount(a or b) for a, b in amounts]
                vals = [v for v in vals if v]
                if len(vals) >= 2:
                    cost, payout = vals[0], vals[1]
                elif vals:
                    cost = vals[0]
                break
    if cost is None:
        unsure.append("the amount risked")
    if payout is None:
        unsure.append("the payout")
    if status == "open" and re.search(r"\brefund(?:ed)?\b", "\n".join(x["text"] for x in lines[:8]), re.I):
        status, returned = "push", cost                         # every pick voided: the entry fee came back
    if status == "open":
        for ln in lines[:8]:                                   # the result badge next to the header
            toks = [w["text"].strip(".,:;!()") for w in ln["words"]]
            if "Loss" in toks or "LOSS" in toks or "Lost" in toks:
                status, returned = "loss", 0.0
                break
            if any(t in ("Win", "WIN", "Won") and (i == 0 or toks[i - 1].lower() != "to") for i, t in enumerate(toks)):
                status = "win"
                break
    slip_fams = {FREE_SPORT_FAMILY[x] for x in re.findall(r"\b(NFL|CFB|NCAAF|NBA|WNBA|CBB|NCAAB|NHL|MLB|SOCCER|KBO|NPB"
                                                          r"|CPBL|KHL|SHL|WTA|ATP)P?\b", full)}
    if re.search(r"\b(LoL|CS2|VAL|DOTA|COD)\b", full):
        slip_fams.add("esports")
    teams: dict = {}
    games: dict = {}
    headers = [ln for ln in lines if re.search(r"vs", ln["text"], re.I) and not _free_stat_in(ln["text"])
               and re.search(r"\b(?:Final|NFL|NBA|NHL|MLB|WNBA|SOCCER|CFB|CBB|LoL|CS2|VAL)\b|\d", ln["text"])]
    extra = free_missing_stats(lines, grey, img)
    if extra:                                   # a box's stat name Tesseract skipped ("Ks" under "3.5"), read again
        lines = sorted(lines + extra, key=lambda ln: (ln["y"], ln["x0"]))
    # legs: anchor on each stat name, take the line number before it, the name above it, and the side
    legs: list[str] = []
    dnp: list[str] = []           # legs marked DNP (the player didn't play: PrizePicks voids that pick)
    goblins: list[str] = []       # r46.4: legs with PrizePicks' green goblin (an easier line that pays less)
    used_lines: set = set()       # a name line belongs to one leg; the same player can be on two lines
    num_hs = sorted(w["h"] for w in words if _FREE_NUM.match(_free_numtext(w["text"])))
    builder = bool(re.search(r"\bless\b", low) and re.search(r"\bmore\b", low))
    for k, ln in enumerate(lines):
        st = _free_stat_in(ln["text"])
        if not st:
            continue
        stat, at = st
        # where the stat sits: on cards with the line in a box on the right, only numbers in that box count
        pos, stat_x = 0, None
        for w in ln["words"]:
            if pos >= at - 1 and stat_x is None:
                stat_x = w["x"]
            pos += len(w["text"]) + 1
        right = stat_x is not None and stat_x > 0.55 * img.width
        # the number: on this line before the stat, else the line(s) just above
        cand_lines = [ln] + [lines[j] for j in range(k - 1, max(-1, k - 3), -1)]
        if right:      # share cards: the number can sit a row or two above the name and team lines
            for j in range(k - 1, max(-1, k - 6), -1):
                if 0 <= ln["y"] - lines[j]["y"] <= 3.5 * max(ln["h"], 20) and lines[j] not in cand_lines:
                    cand_lines.append(lines[j])
        num_words, src = [], None
        whole = None                                          # a bare whole number, used only if no decimal is near
        hn = num_hs[len(num_hs) // 2] if num_hs else 25
        if right:
            for cl in cand_lines[1:]:
                box_ws = [w for w in cl["words"] if w["x"] > 0.55 * img.width]
                if not box_ws:
                    continue
                rw = max(box_ws, key=lambda w: w["x"] + w["w"])
                clean = _free_numtext(rw["text"])
                if "." in clean or len(re.sub(r"\D", "", clean)) > 2:
                    break                                     # a clean number: the usual path reads it
                rr, cy = rw["x"] + rw["w"], rw["y"] + rw["h"] / 2
                fake = {"x": int(rr - 1.8 * hn), "y": int(cy - 0.6 * hn), "w": int(1.8 * hn), "h": int(1.2 * hn),
                        "text": rw["text"], "conf": 100, "_glued": True}
                got = free_reocr_number(grey, fake)
                if got and "." in got:
                    fake["_num"] = got
                    num_words, src = [fake], cl
                break
        for cl in ([] if num_words else cand_lines):
            ws = [w for w in cl["words"] if _FREE_NUM.match(_free_numtext(w["text"]))]
            if right:
                ws = []
                for w in cl["words"]:
                    if w["x"] < 0.55 * img.width:
                        continue                              # avatar and jersey scraps on the left
                    pn = free_pill_num(w["text"])
                    if pn and _FREE_NUM.match(pn):
                        w["_num"] = pn
                        w["_glued"] = not _free_numtext(w["text"]) or not w["text"][:1].isdigit()   # "a5": arrow + 5
                        ws.append(w)
            if cl is ln:
                cut = len(ln["text"][:at])
                pos, kept = 0, []
                for w in cl["words"]:
                    if pos < cut and w in ws:
                        kept.append(w)
                    pos += len(w["text"]) + 1
                ws = kept
            ws = [w for w in ws if not re.search(r"#\s*$", cl["text"][:cl["text"].find(w["text"])])]
            dec = [w for w in ws if re.search(r"[.,]\d$", w.get("_num") or _free_numtext(w["text"]))]
            if dec:
                num_words, src = dec, cl
                break
            if ws and whole is None:
                whole = (ws, cl)
        if not num_words and whole:
            num_words, src = whole
        if not num_words and right and platform == "PrizePicks":
            got = free_box_number(grey, ln, hn)
            if got:
                num_words, src = [got], (lines[k - 1] if k and ln["y"] - lines[k - 1]["y"] < 2.5 * max(hn, ln["h"])
                                         else ln)
        if not num_words:
            continue
        stat = FREE_STAT_ALIAS.get(stat, stat)
        fams = {STATS[x][1] for x in stat_keys_in(stat)} if stat not in FREE_ESPORTS_STATS else {"esports"}
        if slip_fams and fams and not (fams & slip_fams) and "fantasy" not in stat.lower():
            continue                                          # a baseball stat read off a hockey slip: noise
        wd = max(num_words, key=lambda w: w["x"])            # the new line, never a crossed-out old one
        txt = wd.get("_num") or _free_numtext(wd["text"])
        promo = re.fullmatch(r"(\d{1,2})\.?5(\d{1,2})\.?5", txt or "")
        if promo and stat not in FREE_BIG_STATS:     # r46.5: "6515" is a crossed-out 6.5 next to the new 1.5
            txt = promo.group(2) + ".5"
        again = None if wd.get("_boxread") or promo else free_reocr_number(grey, wd)
        if again and (("." in again) or "." not in txt):
            txt = again
        try:
            value = float(txt)
        except ValueError:
            continue
        if platform == "PrizePicks" and right and re.fullmatch(r"\d5", txt):
            value = value / 10                                # the dot lost next to the arrow: '25' is 2.5
        if "." not in txt and value >= 100 and txt.endswith("5") and stat not in ("Pass Yards", "Pass+Rush Yds",
                                                                                   "Rush+Rec Yds", "Pitches Thrown"):
            value = value / 10                                # '495' Rec Yards is 49.5
        if value >= 100 and stat not in FREE_BIG_STATS:
            continue                                          # no line is that high: a misread scrap, not a leg
        # the player: the nearest name at or above the number's line
        name, name_at = None, None
        start = lines.index(src)
        order = [start] + ([start + 1] if start + 1 < len(lines) and lines[start + 1]["y"] - src["y"] < 1.2 * src["h"]
                           else []) + list(range(start - 1, max(-1, start - 4), -1))
        esport = stat in FREE_ESPORTS_STATS
        for j in order:
            name = _free_name(lines[j], 0.55 * img.width if right else None, single=esport)
            if name and j not in used_lines:
                name_at = j
                break
            name = None
        if not name and right:
            name = free_name_reread(grey, src["y"] - 2.2 * src["h"], ln["y"] + 1.6 * ln["h"], esport)
            if name and any(leg.startswith(name + " ") and f" {value:g} {stat}" in leg for leg in legs):
                name = None
        if not name:
            unsure.append(f"a player's name near {value:g} {stat}")
            continue
        if name_at is not None:
            used_lines.add(name_at)
        # the side: More/Less words (the green one when both show), else the arrow beside the number
        side = None
        lo = min(start, name_at if name_at is not None else start)
        near = [w for j in range(lo, min(len(lines), k + 2)) for w in lines[j]["words"]]
        words_low = {w["text"].lower().strip("+-↑↓"): w for w in near}
        if "more" in words_low and "less" in words_low:
            gm, gl = free_green(img, words_low["more"]), free_green(img, words_low["less"])
            side = "over" if gm > gl * 1.5 and gm > 0.08 else ("under" if gl > gm * 1.5 and gl > 0.08 else None)
        elif not builder:
            for word, s in (("more", "over"), ("over", "over"), ("higher", "over"), ("less", "under"),
                            ("under", "under"), ("lower", "under")):
                if word in words_low:
                    side = s
                    break
        if side is None and builder:
            top = lines[lo]["y"] - src["h"]
            bottom = ln["y"] + 2 * ln["h"]
            side = free_green_side(img, top, bottom)
        if side is None:
            left = [w for w in src["words"] if w["x"] + w["w"] <= wd["x"] and w["x"] > wd["x"] - 6 * wd["h"]]
            nums_left = [w for w in left if _FREE_NUM.match(_free_numtext(w["text"]))
                         and len(_free_numtext(w["text"])) > 1]      # a lone "4"/"1" is the arrow, misread
            anchor = min(nums_left, key=lambda w: w["x"]) if nums_left else wd
            glyph = [w for w in left if w not in nums_left and w["x"] + w["w"] <= anchor["x"] + 2
                     and w["x"] > anchor["x"] - 3 * wd["h"]]
            if glyph:
                g = max(glyph, key=lambda w: w["x"])
                box = (g["x"] - 4, wd["y"] - wd["h"] * 0.4, g["x"] + g["w"] + 4, wd["y"] + wd["h"] * 1.4)
            else:
                box = (anchor["x"] - 2.2 * wd["h"], wd["y"] - wd["h"] * 0.4, anchor["x"] - 0.15 * wd["h"],
                       wd["y"] + wd["h"] * 1.4)
            side = free_arrow(img, box)
        if side is None and right and wd.get("_glued"):
            # the arrow glued into the number's word: find it just left of the digits, from the box's right edge
            digits = len(f"{value:g}") + (0 if "." in f"{value:g}" else 1)
            rr, cy = wd["x"] + wd["w"], wd["y"] + wd["h"] / 2
            nw = digits * 0.6 * hn
            side = free_arrow(img, (rr - nw - 1.9 * hn, cy - 0.9 * hn, rr - nw - 0.15 * hn, cy + 0.9 * hn))
        if promo:                                     # r46.5: promo boxes are wide, read the arrow glyph instead
            gl = re.match(r"^[^\d]*", wd.get("text") or "").group(0)
            if not gl:
                left_ = [w for w in src["words"] if w["x"] + w["w"] <= wd["x"] + 2 and len(w["text"]) <= 2]
                gl = max(left_, key=lambda w: w["x"])["text"] if left_ else ""
            if re.search(r"[Tt↑]", gl):
                side = "over"
            elif re.search(r"[JVv↓]", gl):
                side = "under"
        if side is None and right and not wd.get("_boxread"):
            # Tesseract's box for "18.5" took in the arrow too: look just left of where the digits really start
            vt = f"{value:g}"
            hh = wd["h"]
            nw = (len(vt.replace(".", "")) * 0.6 + (0.25 if "." in vt else 0)) * hh
            rr = wd["x"] + wd["w"]
            if wd["w"] > nw + 0.6 * hh and wd["conf"] < 60 and re.fullmatch(r"\d{1,3}(?:\.\d)?", wd["text"]):
                a = free_arrow(img, (rr - nw - 1.6 * hh, wd["y"] - 0.3 * hh, rr - nw - 0.1 * hh, wd["y"] + 1.3 * hh))
                b = free_arrow(img, (wd["x"] - 0.2 * hh, wd["y"] - 0.3 * hh, wd["x"] + 1.2 * hh, wd["y"] + 1.3 * hh))
                side = a if a and a == b else None     # both looks must agree, or we ask
        if side is None:
            unsure.append(f"over or under for {name}")
            side = "over"
        if num_hs and wd["h"] > 1.35 * num_hs[len(num_hs) // 2] and wd.get("conf", 100) < 60:
            unsure.append(f"the line for {name}")           # an arrow glued onto the number
        if wd.get("_boxread") and len(txt.replace(".", "")) < 2:
            unsure.append(f"the line for {name}")           # a lone digit from the re-read box: half a number
        if stat.lower().startswith("anytime") and value > 1.5:
            unsure.append(f"the line for {name}")
            value = 0.5
        leg = f"{name} {side} {value:g} {'Anytime TD' if stat.lower().startswith('anytime') else stat}"
        per = leg_period(ln["text"][at:])
        if per:
            leg += f" ({per})"                                # "Rec Yards (4Q)": a 4th-quarter line, not the game
        for tl in (ln, lines[k + 1] if k + 1 < len(lines) else None):
            hit = None
            if tl is not None and re.search(r"[•·«+\-]|\b(?:QB|RB|WR|TE|C|LW|RW|D|G|SP|RP|PG|SG|SF|PF)\b", tl["text"]):
                hit = next((t for t in _FREE_TEAM_TOKEN.findall(tl["text"][:at] if tl is ln else tl["text"])
                            if t.lower() in TEAM_ABBRS), None)
            if hit:
                teams.setdefault(norm_name(name), hit)
                break
        head = [h for h in headers if h["y"] < src["y"]]
        if head:
            games.setdefault(norm_name(name), re.sub(r"^(?:NFL|NBA|NHL|MLB|WNBA|SOCCER|CFB|CBB|LoL|CS2)\)?\s*", "",
                                                     head[-1]["text"]).strip())
        if leg not in legs:
            legs.append(leg)
            if re.search(r"\bDNP\b", ln["text"] + " " + src["text"]):
                dnp.append(leg)
            if platform == "PrizePicks" and right and free_goblin(img, wd, hn):
                goblins.append(leg)
    if not legs:
        if platform and (cost or payout):
            return {"is_slip": True, "platform": platform, "sport": None, "description": "Slip", "legs": [],
                    "cost": cost, "payout": payout, "status": "open", "returned": None, "game_date": None,
                    "entry_type": entry_type, "placed": True, "_unsure": ["the picks"], "_how": "scan"}
        return None
    if want and len(legs) != want:
        unsure.insert(0, f"all {want} picks (I found {len(legs)})")
    if not platform:
        platform = "PrizePicks" if entry_type else "Other"
        unsure.append("which app it's from")
    placed = not re.search(r"\bsubmit\b|place entry|add picks|entry fee", low)
    n = want or len(legs)
    desc = (f"{n}-Pick {'Flex' if entry_type == 'flex' else 'Power'} Play" if platform in ("PrizePicks", "Underdog")
            else f"{n}-leg slip" if n > 1 else legs[0])
    sports = [s for s in ("NFL", "NBA", "NHL", "MLB", "WNBA", "SOCCER", "CFB", "CBB") if re.search(rf"\b{s}P?\b", full)]
    return {"is_slip": True, "platform": platform, "sport": ", ".join(s.title() if s == "SOCCER" else s for s in sports)
            or None, "description": desc, "legs": legs, "cost": cost, "payout": payout, "status": status,
            "returned": returned, "game_date": None, "entry_type": entry_type, "placed": placed,
            "_unsure": unsure, "_how": "scan", "_teams": teams, "_games": games, "_want": want, "_dnp": dnp,
            "_goblins": goblins}


def free_box_number(grey, ln: dict, hn: float) -> Optional[dict]:
    """The line's number box on a share card, read again when Tesseract skipped the number: the strip just above
    the stat name, right-aligned with it, digits only. A fake word for free_parse, or None."""
    from PIL import Image
    hn = max(18.0, float(hn or 25))
    x1 = ln["x1"]
    box = (int(x1 - 2.7 * hn), max(0, int(ln["y"] - 2.1 * hn)), min(grey.width, int(x1 + 0.4 * hn)),
           max(0, int(ln["y"] - 0.05 * hn)))
    if box[2] - box[0] < 10 or box[3] - box[1] < 10:
        return None
    crop = grey.crop(box)
    crop = crop.resize((crop.width * 3, crop.height * 3), Image.LANCZOS)
    for psm in (7, 8):
        txt = _free_tess(crop, psm, ["-c", "tessedit_char_whitelist=0123456789."], tsv=False).strip()
        txt = re.sub(r"\s+", "", txt)
        m = re.search(r"(\d{1,3}(?:\.\d)?)$", txt)
        if m:
            num = m.group(1)
            if len(num) >= 3 and "." not in num and num[0] in "14" and num[1:] not in ("00",):
                num = num[1:]                 # the arrow read as a 1 or 4 in front: "111" is 11
            return {"text": num, "_num": num, "x": box[0], "y": box[1], "w": box[2] - box[0], "h": box[3] - box[1],
                    "conf": 70, "_boxread": True, "_glued": True}
    return None


def free_goblin(img, wd: dict, hn: float) -> bool:
    """PrizePicks marks a goblin line with a small green face just left of the arrow in the number box."""
    try:
        h = float(wd.get("h") or hn or 25)
        if wd.get("_boxread"):
            h = max(18.0, float(hn or 25))
            x1 = wd["x"] + 0.5 * h
            box = (int(wd["x"] - 3.2 * h), int(wd["y"]), int(x1), int(wd["y"] + wd["h"]))
        else:
            rr = wd["x"] + wd["w"]
            digits = re.sub(r"\D", "", _free_numtext(wd.get("text") or "") or "") or "00"
            nw = (min(len(digits), 4) * 0.6 + 0.25) * h       # the number's own width: the icon sits left of the arrow
            box = (int(rr - nw - 4.4 * h), int(wd["y"] - 0.4 * h), int(rr - nw - 0.6 * h), int(wd["y"] + 1.4 * h))
        box = (max(0, box[0]), max(0, box[1]), min(img.width, box[2]), min(img.height, box[3]))
        if box[2] - box[0] < 6 or box[3] - box[1] < 6:
            return False
        px = img.crop(box).convert("RGB").getdata()
        n = len(px)
        g = sum(1 for r, gg, b in px if gg > 140 and gg > r + 40 and gg > b + 40)
        return n > 0 and g / n >= 0.03
    except Exception:
        return False


def free_name_reread(grey, top: float, bottom: float, single: bool = False) -> Optional[str]:
    """Tesseract sometimes skips a name next to a dark jersey: read that strip of the card again, zoomed in."""
    from PIL import Image
    W = grey.width
    box = (int(0.18 * W), max(0, int(top)), int(0.62 * W), min(grey.height, int(bottom)))
    if box[3] - box[1] < 20:
        return None
    crop = grey.crop(box)
    crop = crop.resize((crop.width * 2, crop.height * 2), Image.LANCZOS)
    words = []
    for row in _free_tess(crop, 6).splitlines()[1:]:
        f = row.split("\t")
        if len(f) < 12 or f[0] != "5" or not f[11].strip():
            continue
        try:
            words.append({"text": f[11].strip(), "conf": float(f[10]), "x": int(f[6]), "y": int(f[7]),
                          "w": int(f[8]), "h": int(f[9]), "line": (int(f[2]), int(f[3]), int(f[4]))})
        except ValueError:
            continue
    for ln in free_lines(words):
        name = _free_name(ln, None, single=single)
        if name:
            return name
    return None


def free_missing_stats(lines: list, grey, img) -> list:
    """Share cards print the stat in small type under the number box. When a box's number has no stat line under it,
    read just that spot again, bigger, and hand back the stat as its own line."""
    from PIL import Image
    W = img.width
    stat_lines = [ln for ln in lines if _free_stat_in(ln["text"])]
    out = []
    jobs = []
    for ln in lines:
        right = [w for w in ln["words"] if w["x"] > 0.6 * W]
        if not right or _free_stat_in(ln["text"]):
            continue
        rw = max(right, key=lambda w: w["x"] + w["w"])
        t = rw["text"]
        if not re.search(r"\d", t) or re.search(r"[:$%]|am$|pm$|20\d\d", t, re.I):
            continue
        h = max(ln["h"], 20)
        if any(0 < s2["y"] - ln["y"] <= 3.5 * h for s2 in stat_lines):
            continue
        box = (int(0.6 * W), int(ln["y"] + 0.7 * h), W, min(grey.height, int(ln["y"] + 3.0 * h)))
        if box[3] - box[1] < 12:
            continue
        crop = grey.crop(box)
        crop = crop.resize((crop.width * 2, crop.height * 2), Image.LANCZOS)
        jobs.append((ln, h, box, crop))
    if not jobs:
        return out
    from concurrent.futures import ThreadPoolExecutor
    with ThreadPoolExecutor(max_workers=min(4, len(jobs))) as ex:
        texts = list(ex.map(lambda j: " ".join(_free_tess(j[3], 7, tsv=False).split()), jobs))
    for (ln, h, box, _), txt in zip(jobs, texts):
        st = _free_stat_in(txt)
        if not st:
            continue
        name = st[0]
        out.append({"words": [{"text": name, "conf": 80, "x": box[0] + 40, "y": int(ln["y"] + 1.3 * h), "w": 20 * len(name),
                               "h": h, "line": ("reread", ln["y"])}], "text": name, "y": int(ln["y"] + 1.3 * h), "h": h,
                    "x0": box[0] + 40, "x1": box[0] + 40 + 20 * len(name)})
    return out



# ---- r32: the scan log (what every screenshot read gave, for the staff page) -------------------------------

def scan_log_db() -> None:
    db().execute("""CREATE TABLE IF NOT EXISTS scan_log (id INTEGER PRIMARY KEY AUTOINCREMENT, guild_id INTEGER,
                    at TEXT, kind TEXT, result TEXT, reader TEXT, legs INTEGER, want INTEGER, reasons TEXT, jump TEXT,
                    user_name TEXT, file_name TEXT)""")
    db().execute("CREATE INDEX IF NOT EXISTS scan_log_g ON scan_log (guild_id, at)")


def scan_log_add(guild_id: int, message, attachment, slip: Optional[dict], reason: Optional[str], kind: str) -> None:
    """One row per screenshot read: ok / unsure / failed, which reader, how many legs, why. Never the image itself."""
    try:
        scan_log_db()
        legs = len((slip or {}).get("legs") or [])
        unsure = list((slip or {}).get("_unsure") or [])
        result = "failed" if not slip or not legs else ("unsure" if unsure else "ok")
        why = unsure[:4] if unsure else ([reason] if reason and result == "failed" else [])
        db().execute("INSERT INTO scan_log (guild_id, at, kind, result, reader, legs, want, reasons, jump, user_name, file_name) "
                     "VALUES (?,?,?,?,?,?,?,?,?,?,?)",
                     (guild_id, now_iso(), kind, result, clip(str((slip or {}).get("_how") or ""), 20), legs,
                      (slip or {}).get("_want"), json.dumps([clip(str(x), 120) for x in why]),
                      clip(str(getattr(message, "jump_url", "") or ""), 200),
                      clip(getattr(getattr(message, "author", None), "display_name", "") or "", 40),
                      clip(getattr(attachment, "filename", "") or "", 80)))
        db().execute("DELETE FROM scan_log WHERE id IN (SELECT id FROM scan_log WHERE guild_id = ? ORDER BY id DESC "
                     "LIMIT -1 OFFSET 500)", (guild_id,))
        db().commit()
    except Exception:
        log.warning("Scan log write failed", exc_info=True)


def scan_log_rows(guild_id: int, limit: int = 40) -> list:
    try:
        scan_log_db()
        rows = db().execute("SELECT * FROM scan_log WHERE guild_id = ? ORDER BY id DESC LIMIT ?",
                            (guild_id, limit)).fetchall()
    except Exception:
        return []
    out = []
    for r in rows:
        try:
            why = json.loads(r["reasons"] or "[]")
        except ValueError:
            why = []
        out.append({"at": r["at"], "kind": r["kind"], "result": r["result"], "reader": r["reader"], "legs": r["legs"],
                    "want": r["want"], "why": why, "jump": r["jump"] if (r["jump"] or "").startswith("https://discord.com/")
                    else None, "who": r["user_name"]})
    return out


def scan_log_stats(guild_id: int, days: int = 7) -> dict:
    try:
        scan_log_db()
        since = iso(datetime.now(timezone.utc) - timedelta(days=days))
        rows = db().execute("SELECT result, COUNT(*) AS n FROM scan_log WHERE guild_id = ? AND at >= ? GROUP BY result",
                            (guild_id, since)).fetchall()
    except Exception:
        return {"ok": 0, "unsure": 0, "failed": 0}
    out = {"ok": 0, "unsure": 0, "failed": 0}
    for r in rows:
        out[r["result"]] = int(r["n"])
    return out

def free_scan(raw: bytes) -> Optional[dict]:
    """The whole free scan on one image (sync, for a worker thread)."""
    t0 = time.monotonic()
    img, grey, scale = free_prepare(raw)
    out = free_parse(free_words(grey), img, grey)
    if out and out.get("_unsure") and scale >= 2.2:
        out["_unsure"].append("the screenshot is small or blurry: a full-size one reads better")
    ms = int((time.monotonic() - t0) * 1000)
    try:
        RELIABILITY.setdefault("scan_ms", []).append(ms)
        RELIABILITY["scan_ms"] = RELIABILITY["scan_ms"][-60:]
    except Exception:
        pass
    return out


# ---- names: the scan's spelling checked against ESPN's players ---------------------------------------

async def free_fix_names(slip: dict) -> None:
    """'Julian Quifiones' -> 'Julián Quiñones' when ESPN has one clear match (best effort, a few seconds)."""
    async def found(name: str) -> list:
        try:
            raw = await asyncio.wait_for(_get_json(ESPN_SEARCH, {"query": name, "limit": 5, "type": "player"}), 6)
            return [it.get("displayName") or "" for it in (raw.get("items") or []) if isinstance(it, dict)]
        except Exception:
            return []
    namefix_apply(slip)
    legs = slip.get("legs") or []
    shapes = [re.match(r"^(.+?) (over|under) ([\d.]+) (.+)$", leg) for leg in legs]
    names = list(dict.fromkeys(m.group(1) for m in shapes if m))
    looked = dict(zip(names, await asyncio.gather(*(found(n) for n in names))))
    fixed = []
    for leg, m in zip(legs, shapes):
        if not m:
            fixed.append(leg)
            continue
        name = m.group(1)
        items = looked.get(name) or []
        best, score = None, 0.0
        for it in items:
            r = difflib.SequenceMatcher(None, norm_name(name), norm_name(it)).ratio()
            if r > score:
                best, score = it, r
        parts = name.split()
        if score < 0.8 and len(parts) >= 3 and len(parts[0]) <= 4:
            rest = " ".join(parts[1:])
            for it in await found(rest):
                r = difflib.SequenceMatcher(None, norm_name(rest), norm_name(it)).ratio()
                if r >= 0.9 and r > score:
                    best, score = it, r
        if best and score >= 0.8 and norm_name(best) != norm_name(name):
            old = norm_name(name)
            name = best
            for k in ("_teams", "_games"):
                if old in (slip.get(k) or {}):
                    slip[k][norm_name(best)] = slip[k].pop(old)
        fixed.append(f"{name} {m.group(2)} {m.group(3)} {m.group(4)}")
    slip["legs"] = fixed


# ---- Gemini (Google's free tier) ------------------------------------------------------------------

async def read_slip_gemini(attachment) -> Optional[dict]:
    """Same job as read_slip, through Gemini. The key goes in a header, never the URL."""
    import aiohttp
    raw = await attachment.read()
    if len(raw) > MAX_IMAGE_BYTES:
        raise SecImageTooBig(f"{len(raw) // 1024} KB")
    try:
        pngs = await asyncio.to_thread(enlarge_slip, raw)
    except Exception:
        pngs = [raw]
    parts = [{"inline_data": {"mime_type": "image/png", "data": base64.standard_b64encode(b).decode()}} for b in pngs[:5]]
    prompt = SLIP_PROMPT
    if len(pngs) > 1:
        prompt = (f"These {len(pngs)} images are ONE screenshot: the first is the whole thing, the rest are enlarged "
                  "slices of it from top to bottom that overlap a little. Count each leg only once.\n\n" + prompt)
    prompt += f"\n\nToday is {datetime.now(TZ):%A, %B %d, %Y}."
    parts.append({"text": prompt})
    body = {"contents": [{"parts": parts}], "generationConfig": {"temperature": 0, "responseMimeType": "application/json"}}
    url = f"https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent"
    async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=60)) as session:
        async with session.post(url, json=body, headers={"x-goog-api-key": GEMINI_API_KEY}) as resp:
            if resp.status != 200:
                text = (await resp.text())[:300]
                raise RuntimeError(f"Gemini HTTP {resp.status}: {text}")
            data = await resp.json(content_type=None)
    text = "".join(p.get("text", "") for c in (data.get("candidates") or [])[:1]
                   for p in ((c.get("content") or {}).get("parts") or []))
    slip = extract_json(text)
    if not slip.get("is_slip"):
        return None
    slip["cost"] = as_amount(slip.get("cost"))
    slip["payout"] = as_amount(slip.get("payout"))
    slip["returned"] = as_amount(slip.get("returned"))
    if slip.get("status") not in ("open", "win", "loss", "push"):
        slip["status"] = "open"
    slip["placed"] = slip.get("placed") is not False
    return slip


# ---- the chain ------------------------------------------------------------------------------------

async def read_slip_best(attachment) -> tuple[Optional[dict], Optional[str]]:
    """Free scan first, then Gemini, then Claude. Returns (slip or None, why it failed or None). A slip the scan
    wasn't sure about comes back with '_unsure' (reasons) when no AI reader could do better: confirm it by hand."""
    reason, unsure_slip = None, None
    for reader in SLIP_READERS:
        if reader == "scan" and TESSERACT:
            try:
                raw = await attachment.read()
                if len(raw) > MAX_IMAGE_BYTES:
                    raise SecImageTooBig(f"{len(raw) // 1024} KB")
                slip = await asyncio.to_thread(free_scan, raw)
            except SecImageTooBig:
                raise
            except Exception as exc:
                log.warning("Free slip scan failed", exc_info=True)
                SLIP_STATE["last_error"] = (now_iso(), f"Free scan: {type(exc).__name__}: {exc}"[:300])
                continue
            if slip is None:
                reason = reason or "it didn't look like a bet slip to me"
                continue
            try:
                await free_fix_names(slip)
            except Exception:
                log.debug("Name check skipped", exc_info=True)
            if not slip["_unsure"] and slip["legs"]:
                free_count("scan")
                slip.pop("_unsure", None)
                return slip, None
            unsure_slip = slip
            continue
        if reader == "gemini" and GEMINI_API_KEY:
            try:
                slip = await read_slip_gemini(attachment)
            except SecImageTooBig:
                raise
            except Exception as exc:
                log.warning("Gemini slip read failed: %s", str(exc)[:200])
                SLIP_STATE["last_error"] = (now_iso(), f"Reading with Gemini: {type(exc).__name__}: {str(exc)[:200]}")
                continue
            if slip and slip.get("cost") is not None:
                free_count("gemini")
                slip["_how"] = "gemini"
                return slip, None
            reason = "I couldn't make out the amount risked" if slip else reason
            continue
        if reader == "claude" and ai_enabled() and claude_budget_ok(essential=True):
            slip, why = await read_slip_claude(attachment)
            if slip is not None and slip.get("cost") is not None:
                free_count("claude")
                slip["_how"] = "claude"
                return slip, None
            reason = why or reason
    if unsure_slip is not None:
        return unsure_slip, None
    return None, reason


def free_unsure_note(slip: dict) -> str:
    bits = slip.get("_unsure") or []
    return ("🔎 I read this with the free scan but couldn't be sure about " + ", ".join(bits[:3])
            + (" and more" if len(bits) > 3 else "") + ". Check it, then tap 🧾 **Log this slip** (or ✏️ **Edit** to fix it).")


HELP_EXTRA.append(("🔎 Reading slips for free", (
    "Screenshots are read by a free text scan first. If it's sure, the slip logs like before; if not, you get a "
    "card to check and tap 🧾 **Log this slip** (or ✏️ Edit). A free `GEMINI_API_KEY` on Railway adds a second free reader, "
    "and Claude is only the last resort. `/admin status` shows which reader handled today's slips.")))


# ---- questions: Gemini's free tier first (with Google Search), Claude as the backup ---------------------------

ASK_ENGINES = [x.strip().lower() for x in env("ASK_ENGINES", "groq,cerebras,openrouter,gemini,claude").split(",")
               if x.strip()]
ENGINE_NAMES = {"groq": "Groq (free)", "cerebras": "Cerebras (free)", "openrouter": "OpenRouter (free)",
                "gemini": "Gemini (free)", "claude": "Claude (paid)"}
ENGINE_COOL: dict = {}             # engine -> (monotonic time it's usable again, why)
ENGINE_STRIKES: dict = {}          # engine -> limit errors in a row


def engine_key_set(engine: str) -> bool:
    return bool({"groq": GROQ_API_KEY, "cerebras": CEREBRAS_API_KEY, "openrouter": OPENROUTER_API_KEY,
                 "gemini": GEMINI_API_KEY}.get(engine)) or (engine == "claude" and ai_enabled())


def engine_cooling(engine: str) -> Optional[str]:
    hit = ENGINE_COOL.get(engine)
    if hit and hit[0] > time.monotonic():
        return hit[1]
    return None


def engine_note(engine: str, ok: bool, tokens: int = 0, err: Optional[str] = None) -> None:
    """Today's use of each AI service (for the staff page), and a cool-down when a service says its free limit is hit:
    15 minutes for a per-minute limit, until midnight for a daily one."""
    key = f"engines:{datetime.now(TZ).date().isoformat()}"
    try:
        data = json.loads(get_setting(0, key) or "{}")
    except ValueError:
        data = {}
    e = data.setdefault(engine, {"ok": 0, "fail": 0, "tokens": 0})
    e["ok" if ok else "fail"] += 1
    e["tokens"] += max(0, int(tokens or 0))
    if ok:
        ENGINE_STRIKES.pop(engine, None)
    if err:
        e["last_error"] = clip(sec_redact(err), 160)
        low = err.lower()
        if "429" in err or "rate limit" in low or "quota" in low or "exhausted" in low:
            daily = any(w in low for w in ("per day", "perday", "daily", "rpd", "tpd"))
            strikes = ENGINE_STRIKES[engine] = ENGINE_STRIKES.get(engine, 0) + 1
            now = datetime.now(TZ)
            if daily:
                wait = ((now.replace(hour=0, minute=0, second=0, microsecond=0) + timedelta(days=1)) - now).total_seconds()
                ENGINE_COOL[engine] = (time.monotonic() + wait, "free limit used up for today")
            elif strikes >= 2:
                ENGINE_COOL[engine] = (time.monotonic() + 120, "busy for a couple of minutes")
            e["limited_at"] = now_iso()
    set_setting(0, key, json.dumps(data))


def engine_usage() -> list:
    try:
        data = json.loads(get_setting(0, f"engines:{datetime.now(TZ).date().isoformat()}") or "{}")
    except ValueError:
        data = {}
    out = []
    for eng in dict.fromkeys(ASK_ENGINES + ["groq", "cerebras", "openrouter", "gemini", "claude"]):
        d = data.get(eng) or {}
        out.append({"engine": eng, "name": ENGINE_NAMES.get(eng, eng), "on": engine_key_set(eng),
                    "in_pool": eng in ASK_ENGINES, "ok": int(d.get("ok") or 0), "fail": int(d.get("fail") or 0),
                    "tokens": int(d.get("tokens") or 0), "cooling": engine_cooling(eng),
                    "error": d.get("last_error")})
    return out


async def ask_compat(engine: str, system: str, user_text: str) -> tuple[str, list[str], int]:
    """(answer, [], tokens used) from an OpenAI-style free service (Cerebras or OpenRouter). Each model is tried in
    turn; a model that's busy or out of free uses hands off to the next."""
    import aiohttp
    url, key, models = {"cerebras": ("https://api.cerebras.ai/v1/chat/completions", CEREBRAS_API_KEY, CEREBRAS_MODELS),
                        "openrouter": ("https://openrouter.ai/api/v1/chat/completions", OPENROUTER_API_KEY,
                                       OPENROUTER_MODELS)}[engine]
    headers = {"Authorization": f"Bearer {key}"}
    if engine == "openrouter":
        headers.update({"HTTP-Referer": f"https://{PUBLIC_DOMAIN}" if PUBLIC_DOMAIN else "https://discord.com",
                        "X-Title": "PIMP-BOT"})
    errors = []
    async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=120)) as session:
        for model in models:
            body = {"model": model, "temperature": 0.4, "max_tokens": 2048,
                    "messages": [{"role": "system", "content": system}, {"role": "user", "content": user_text}]}
            try:
                async with session.post(url, json=body, headers=headers) as resp:
                    if resp.status != 200:
                        err = f"{ENGINE_NAMES[engine].split()[0]} HTTP {resp.status}: {(await resp.text())[:200]}"
                        if resp.status in (401, 403):
                            raise RuntimeError(err)
                        errors.append(err)
                        continue
                    data = await resp.json(content_type=None)
            except RuntimeError:
                raise
            except Exception as exc:
                errors.append(f"{engine} timed out or dropped ({type(exc).__name__})")
                continue
            msg = ((data.get("choices") or [{}])[0].get("message") or {})
            text = re.sub(r"<think>.*?</think>", "", msg.get("content") or "", flags=re.S).strip()
            if text:
                return text, [], int(((data.get("usage") or {}).get("total_tokens")) or 0)
            errors.append(f"{engine} came back empty on {model}")
    raise RuntimeError(" | ".join(errors) or f"{engine} came back empty")


GEMINI_FALLBACK_MODELS = ("gemini-flash-latest", "gemini-2.5-flash", "gemini-2.0-flash")


def gemini_models() -> list[str]:
    """The configured model first, then stable names, so a renamed model doesn't break answers."""
    return list(dict.fromkeys([GEMINI_MODEL, *GEMINI_FALLBACK_MODELS]))


ASK_LAST_ERROR: dict = {"text": None}


def ask_error_hint(exc: Optional[BaseException]) -> str:
    """A short, safe reason for a failed answer (never the key)."""
    t = str(exc or "")
    if "429" in t or "quota" in t.lower() or "exhausted" in t.lower():
        return "Gemini's free limit is used up for now"
    if "401" in t or "403" in t or "API key" in t:
        return "the Gemini key on Railway was refused"
    if "none of the model names" in t:
        return "Gemini doesn't recognise the model name (GEMINI_MODEL)"
    if "no question engine" in t:
        return "no AI key is set on Railway"
    if "timed out" in t.lower():
        return "Gemini took too long to answer"
    if re.search(r"HTTP 5\d\d", t):
        return "Gemini is overloaded on Google's side; try again in a minute"
    if "came back empty" in t:
        return "Gemini came back with no text"
    code = re.search(r"HTTP (\d{3})", t)
    return f"error {code.group(1)}: {ask_error_snip(t)}" if code else f"didn't answer: {ask_error_snip(t)}"


def ask_error_snip(t: str) -> str:
    """A short piece of an error to show in Discord, with anything key-like blanked out."""
    t = re.sub(r"(AIza[\w-]{10,}|sk-[\w-]{10,}|key=[^&\s]+)", "[key]", str(t or ""))
    t = re.sub(r"^(?:Gemini|Groq) HTTP \d{3}:\s*", "", t)
    m = re.search(r"['\"]message['\"]\s*:\s*['\"]([^'\"]{4,})", t)
    return clip(" ".join((m.group(1) if m else t).split()), 90) or type(t).__name__


def claude_error_hint(exc: Optional[BaseException]) -> str:
    t = str(exc or "")
    low = t.lower()
    if "credit balance" in low or "billing" in low:
        return "the Claude account is out of credits"
    if "authentication" in low or "401" in t or "invalid x-api-key" in low:
        return "the Claude key on Railway was refused"
    if "overloaded" in low or "529" in t or "rate_limit" in low or "429" in t:
        return "Claude is busy; try again in a minute"
    return f"didn't answer: {ask_error_snip(t)}"


def ask_enabled() -> bool:
    """Can the bot answer questions at all (any AI key in the pool)?"""
    return any(engine_key_set(e) for e in ASK_ENGINES)


def groq_models(search: bool) -> list[tuple[str, bool]]:
    """[(model, search the web?)]: the main model first, then the fallbacks."""
    return [(m, search and m in GROQ_SEARCH_OK) for m in dict.fromkeys([GROQ_MODEL, *GROQ_FALLBACK_MODELS])]


async def ask_groq(system: str, user_text: str, search: bool = True) -> tuple[str, list[str]]:
    """(answer, source links) from Groq's free tier. A model that's busy or out of free uses hands off to the next."""
    import aiohttp
    errors = []
    async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=150)) as session:
        for model, web in groq_models(search):
            body = {"model": model, "temperature": 0.4, "max_completion_tokens": 4096,
                    "messages": [{"role": "system", "content": system}, {"role": "user", "content": user_text}]}
            if model.startswith("openai/gpt-oss"):
                body["reasoning_effort"] = "low"
            if web:
                body.update(tools=[{"type": "browser_search"}], tool_choice="auto")
            data, tried_plain = None, False
            while True:
                try:
                    async with session.post("https://api.groq.com/openai/v1/chat/completions", json=body,
                                            headers={"Authorization": f"Bearer {GROQ_API_KEY}"}) as resp:
                        if resp.status == 400 and "tools" in body and not tried_plain:
                            body = {k: v for k, v in body.items() if k not in ("tools", "tool_choice")}
                            tried_plain = True                          # search not allowed here: answer without it
                            continue
                        if resp.status != 200:
                            err = f"Groq HTTP {resp.status}: {(await resp.text())[:200]}"
                            if resp.status in (401, 403):
                                raise RuntimeError(err)                 # a bad key fails on every model
                            errors.append(err)
                            break
                        data = await resp.json(content_type=None)
                        break
                except RuntimeError:
                    raise
                except Exception as exc:
                    errors.append(f"Groq timed out or dropped ({type(exc).__name__})")
                    break
            if data is None:
                continue
            msg = ((data.get("choices") or [{}])[0].get("message") or {})
            text = re.sub(r"<think>.*?</think>", "", msg.get("content") or "", flags=re.S)
            text = re.sub(r"【[^】]{0,40}】", "", text).strip()               # browser_search citation marks
            if text:
                sources = []
                for tool in msg.get("executed_tools") or []:
                    for r in ((tool.get("search_results") or {}).get("results") or []):
                        u = str(r.get("url") or "").strip()
                        if u.startswith("https://") and u not in sources:
                            sources.append(u)
                return text, sources[:3]
            errors.append(f"Groq came back empty on {model}")
    log.warning("Groq tried %s: %s", ", ".join(m for m, _ in groq_models(search)), " | ".join(errors)[:600])
    raise RuntimeError(" | ".join(errors) or "Groq came back empty")


def groq_error_hint(exc: Optional[BaseException]) -> str:
    t = str(exc or "")
    if "429" in t:
        return "Groq's free limit is used up for now"
    if "401" in t or "403" in t:
        return "the Groq key on Railway was refused"
    if "timed out" in t:
        return "Groq took too long"
    if re.search(r"HTTP 5\d\d", t):
        return "Groq is busy; try again in a minute"
    return "Groq didn't answer: " + ask_error_snip(t)


async def ask_gemini(system: str, user_text: str, search: bool = True) -> tuple[str, list[str]]:
    """(answer, source links) from Gemini, searching Google for anything current. The key goes in a header."""
    import aiohttp
    system = (system + "\n\nYou don't have a group_stats tool here: for the group's own records use only the group "
              "data included in the message, and say so if it isn't there.")
    body = {"system_instruction": {"parts": [{"text": system}]},
            "contents": [{"role": "user", "parts": [{"text": user_text}]}],
            "tools": [{"google_search": {}}],
            "generationConfig": {"temperature": 0.4, "maxOutputTokens": 8192}}
    if not search:
        body.pop("tools")                                      # the numbers are in the message: save the search quota
    data, text, errors = None, "", []
    async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=150)) as session:
        for model in gemini_models():
            url = f"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent"
            mbody, tried_plain, data = body, False, None
            while True:
                try:
                    async with session.post(url, json=mbody, headers={"x-goog-api-key": GEMINI_API_KEY}) as resp:
                        if resp.status == 400 and not tried_plain and "tools" in mbody:
                            mbody = {k: v for k, v in mbody.items() if k != "tools"}   # no search on this model
                            tried_plain = True
                            continue
                        if resp.status == 404:
                            errors.append(f"{model} not found")
                            break                                               # unknown model: try the next
                        if resp.status != 200:
                            err = f"Gemini HTTP {resp.status}: {(await resp.text())[:200]}"
                            if resp.status in (401, 403) or "API key" in err:
                                raise RuntimeError(err)                         # a bad key fails on every model
                            errors.append(err)
                            break                                               # busy / limit hit: next model
                        data = await resp.json(content_type=None)
                        break
                except RuntimeError:
                    raise
                except Exception as exc:                                        # timeout, connection dropped
                    errors.append(f"Gemini timed out or dropped ({type(exc).__name__})")
                    break
            if data is None:
                continue
            if not data.get("candidates") and (data.get("promptFeedback") or {}).get("blockReason"):
                return "", []                                                   # blocked: the fallback decides
            cand = (data.get("candidates") or [{}])[0]
            text = "".join(p.get("text", "") for p in ((cand.get("content") or {}).get("parts") or [])
                           if not p.get("thought")).strip()
            if text:
                break
            errors.append(f"Gemini came back empty on {model} ({cand.get('finishReason') or 'no reason given'})")
    if not text:
        if errors and all(e.endswith("not found") for e in errors):
            raise RuntimeError("Gemini: none of the model names worked (check GEMINI_MODEL)")
        log.warning("Gemini tried %s: %s", ", ".join(gemini_models()), " | ".join(errors)[:600])
        raise RuntimeError(" | ".join(e for e in errors if not e.endswith("not found")) or "Gemini came back empty")
    sources = []
    for ch in ((cand.get("groundingMetadata") or {}).get("groundingChunks") or []):
        uri = ((ch.get("web") or {}).get("uri") or "").strip()
        if uri.startswith("https://") and uri not in sources:
            sources.append(uri)
    return text, sources[:3]


_NO_ANSWER = re.compile(r"\b(i (?:couldn'?t|could not|can'?t|cannot|wasn'?t able to|was unable to|don'?t have|do not have)"
                        r" (?:find|access|confirm|verify|browse|search|look up|get|provide|give)|unable to (?:find|access|"
                        r"confirm|verify)|no (?:recent |current |reliable )?(?:information|info|results|data) (?:on|about|for|"
                        r"available)|my knowledge cutoff|as of my last (?:update|training)"
                        r"|i(?:'m| am) (?:not able|unable) to (?:find|access|confirm|verify|browse|search|look up|get)"
                        r"|(?:don'?t|do not) have (?:real[- ]time|live|current|up[- ]to[- ]date|recent) (?:access|data|info|"
                        r"information|stats|results)|couldn'?t locate|there (?:is|was|are) no (?:recent |current |reliable )?"
                        r"(?:information|info|data|news|reports?)\b)", re.I)


def ask_unanswered(answer: str) -> bool:
    """Did the answer duck the question (empty, a few words, or 'I couldn't find...')?"""
    a = (answer or "").strip()
    m = _NO_ANSWER.search(a[:400])
    return len(a) < 20 or bool(m and (m.start() < 120 or len(a) < 200))   # a late hedge in a real answer is fine


async def ask_any(system: str, user_text: str, search: bool = True) -> tuple[str, list[str]]:
    """Answer with Gemini (free) first. Claude is the fail-safe: it only runs when Gemini errors out or comes back
    without a real answer (and a Claude key is set). ASK_ENGINES can change the order."""
    last: Optional[Exception] = None
    fallback: Optional[tuple[str, list[str]]] = None
    why: list[str] = []
    ASK_LAST_ERROR["text"] = None
    for engine in ASK_ENGINES:
        cool = engine_cooling(engine) if engine_key_set(engine) else None
        if cool:
            why.append(f"{ENGINE_NAMES.get(engine, engine)}: {cool}")
            continue
        if engine == "groq" and GROQ_API_KEY:
            try:
                answer, sources = await ask_groq(system, user_text, search)
                engine_note("groq", bool(answer))
                if answer and not ask_unanswered(answer):
                    free_count("ask_groq")
                    return answer, sources
                if answer and fallback is None:
                    fallback = (answer, sources)
            except Exception as exc:
                last = exc
                engine_note("groq", False, err=str(exc))
                why.append(groq_error_hint(exc))
                log.warning("Groq answer failed: %s", str(exc)[:300])
        elif engine in ("cerebras", "openrouter") and engine_key_set(engine):
            try:
                answer, sources, used = await ask_compat(engine, system, user_text)
                engine_note(engine, bool(answer), used)
                if answer and not ask_unanswered(answer):
                    free_count("ask_" + engine)
                    return answer, sources
                if answer and fallback is None:
                    fallback = (answer, sources)
            except Exception as exc:
                last = exc
                engine_note(engine, False, err=str(exc))
                why.append(f"{ENGINE_NAMES[engine]}: " + ("its free limit is used up for now" if "429" in str(exc)
                                                          else "the key on Railway was refused" if re.search(r"HTTP 40[13]", str(exc))
                                                          else ask_error_snip(str(exc))))
                log.warning("%s answer failed: %s", engine, str(exc)[:300])
        elif engine == "gemini" and GEMINI_API_KEY:
            try:
                answer, sources = await ask_gemini(system, user_text, search=search)
                engine_note("gemini", bool(answer))
                if answer and not ask_unanswered(answer):
                    free_count("ask_gemini")
                    return answer, sources
                if answer:
                    fallback = (answer, sources)       # keep it in case nothing better comes
                else:
                    why.append("Gemini: it blocked or skipped the request")
            except Exception as exc:
                last = exc
                engine_note("gemini", False, err=str(exc))
                h = ask_error_hint(exc)
                why.append(h if "Gemini" in h else "Gemini: " + h)
                log.warning("Gemini answer failed: %s", str(exc)[:300])
        elif engine == "claude" and ai_enabled() and claude_budget_ok(essential=True):
            try:
                answer, sources = await ask_claude(system, user_text)
            except Exception as exc:
                last = exc
                why.append("Claude backup: " + claude_error_hint(exc))
                log.warning("Claude answer failed: %s", str(exc)[:300])
                continue
            if answer:
                engine_note("claude", True)
                free_count("ask_claude")
                return answer, sources
    if fallback is not None:
        free_count("ask_gemini")
        return fallback
    ASK_LAST_ERROR["text"] = "; ".join(why) if why else ask_error_hint(last or RuntimeError("no question engine is set up"))
    raise last or RuntimeError("no question engine is set up")


# ==========================================================================
# r24: /live as a big, easy-to-read picture with a pace graph per leg, and /gamecard on demand.
# ==========================================================================

LV2_GAMES = 4                 # games drawn on one /live picture
LV2_ROWS = 7                  # legs drawn per game
# (periods, minutes per period) for working out how much of a game is gone
LV2_CLOCK = {"basketball/nba": (4, 12), "basketball/wnba": (4, 10), "basketball/mens-college-basketball": (2, 20),
             "football/nfl": (4, 15), "football/college-football": (4, 15), "hockey/nhl": (3, 20)}


def lv2_elapsed(ev: dict, path: Optional[str]) -> Optional[float]:
    """How much of the game has been played (0-1), from the period and clock; None when it can't tell."""
    if not ev or ev.get("state") != "in":
        return 1.0 if ev and (ev.get("final") or ev.get("state") == "post") else None
    detail = (ev.get("detail") or "").lower()
    fam = (path or "").split("/")[0]
    if fam == "soccer":
        m = re.search(r"(\d{1,3})(?:\+\d+)?'", detail)
        if m:
            return min(1.0, int(m.group(1)) / 90)
        if re.search(r"\b(ft|aet|full[- ]?time|pens?)\b", detail):
            return 1.0
        return 0.5 if re.search(r"\bht\b|half", detail) else None
    if fam == "baseball":
        m = re.search(r"(top|bot|bottom|mid|middle|end)\w*\s+(?:of\s+)?(\d{1,2})", detail)
        if not m:
            return None
        inning = int(m.group(2))
        half = {"top": 0.0, "mid": 0.5, "middle": 0.5, "bot": 0.5, "bottom": 0.5, "end": 1.0}[m.group(1)]
        return max(0.0, min(1.0, (inning - 1 + half) / 9))
    spec = LV2_CLOCK.get(path or "")
    if not spec:
        return None
    periods, mins = spec
    if "halftime" in detail or detail.strip() in ("half", "ht"):
        return 0.5
    if re.search(r"\b\d?ot\b", detail) and not ev.get("period"):
        return 1.0                             # "OT", "2OT" without a period number
    period = int(ev.get("period") or 0)
    if not period:
        m = re.search(r"\b[qp](\d)\b|(\d)(?:st|nd|rd|th)\b", detail)
        period = int(m.group(1) or m.group(2)) if m else 0
    if not period:
        return None
    if period > periods or "ot" in detail.split():
        return 1.0
    m = re.search(r"(\d{1,2}):(\d{2})", detail)
    left = (int(m.group(1)) + int(m.group(2)) / 60) if m else (
        0.0 if ("end" in detail or "intermission" in detail) else mins / 2)
    return max(0.0, min(1.0, ((period - 1) * mins + (mins - min(left, mins))) / (periods * mins)))


def lv2_pace(value: float, line: float, elapsed: Optional[float], text: str) -> Optional[float]:
    """Where this stat is headed if it keeps this rate (None early in a game, or for 'longest' stats)."""
    if elapsed is None or elapsed < 0.12 or elapsed >= 0.999 or re.search(r"longest|first|anytime", text, re.I):
        return None
    return round(value / elapsed, 1)


def lv2_game_rows(g: dict, show_open_only: bool = True) -> list[dict]:
    rows = [lv_row(r["s"], r["e"]) for r in g["rows"]
            if r["s"]["p"]["status"] == "open" or r["e"].get("status") != "open" or not show_open_only]
    return sorted(rows, key=lambda r: (LV_ORDER.get(r["state"], 9), r["who"].lower()))


async def lv2_board_data(client, gid: int, scope: str, uid: int, private: bool, now: datetime,
                         snap: list[dict]) -> Optional[dict]:
    """Everything the /live picture needs (avatars fetched here, before the render thread). None if nothing is live."""
    mine = [s for s in snap if lv_visible(s, scope, uid, private)]
    games = [g for g in lv_games_of(mine).values() if g["ev"].get("state") == "in" and not g["ev"].get("final")]
    games.sort(key=lambda g: (event_time(g["ev"]) or now, g["id"]))
    out, uids = [], set()
    for g in games:
        rows = lv2_game_rows(g)
        if not rows:
            continue
        el = lv2_elapsed(g["ev"], g["path"])
        for r in rows:
            n = r.get("num")
            r["pace"] = lv2_pace(n["value"], n["line"], el, r["text"]) if n and r["state"] not in ("cleared", "dead") else None
            if r.get("uid"):
                uids.add(r["uid"])
        away, home = (dict(t) for t in lv_sides(g["ev"]))
        await lv2_attach_logos(away, home)
        ac = lv_team_colour(away)
        out.append({"league": LEAGUE_NAMES.get(g["path"] or "", ""), "away": dict(away, colour=ac),
                    "home": dict(home, colour=lv_team_colour(home, avoid=ac)), "status": lv_status_text(g["ev"]),
                    "elapsed": el, "rows": rows})
        if len(out) >= LV2_GAMES:
            break
    if not out:
        return None
    avatars = {}
    for u in list(uids)[:24]:
        user = await known_user(client, u)
        avatars[u] = await avatar_bytes(user) if user is not None else None
    heads = await design_rows_heads([r for g in out for r in g["rows"]])
    tonight = [(lv_clock(t), name, n) for t, name, n in lv_tonight(mine, now)]
    more = max(0, len([g for g in lv_games_of(mine).values() if g["ev"].get("state") == "in"]) - len(out))
    return {"title": "LIVE NOW", "who": "everyone" if scope == "a" else "just you" if private else "mine",
            "updated": lv_clock(now), "games": out, "tonight": tonight, "avatars": avatars, "more_games": more,
            "heads": heads}


def _lv2_pace_bar(d, x: int, y: int, w: int, h: int, value: float, line: float, pace: Optional[float], side: str,
                  state: str) -> None:
    """The graph: a filled bar for now, a ghost bar for where it's headed, and a white tick at the line."""
    top = max(line * 1.5, value, pace or 0, 1)
    sx = lambda v: x + w * min(1.0, max(0.0, v / top))
    d.rounded_rectangle((x, y, x + w, y + h), h // 2, fill=(44, 44, 58))
    good = (value > line) if side == "over" else (value <= line)
    col = {"cleared": ART_GREEN, "dead": ART_RED, "close": ART_AMBER}.get(state) or (ART_GREEN if good and side == "over"
                                                                                     else ART_BLUE)
    if side == "under":
        col = ART_RED if value > line else (ART_AMBER if state == "close" else ART_GREEN)
    if pace is not None and pace > value:
        on = (pace > line) if side == "over" else (pace <= line)
        ghost = _brand_mix(ART_GREEN if on else ART_RED, (44, 44, 58), 0.55)
        d.rounded_rectangle((x, y, sx(pace), y + h), h // 2, fill=ghost)
    if value > 0:
        d.rounded_rectangle((x, y, max(x + h, sx(value)), y + h), h // 2, fill=col)
    lx = sx(line)
    d.rectangle((lx - 2, y - 7, lx + 2, y + h + 7), fill=(255, 255, 255))


async def lv2_live_payload(client, gid: int, scope: str, uid: int, private: bool, now: Optional[datetime] = None,
                           snap: Optional[list] = None, until: Optional[datetime] = None):
    """(embed, signature, picture or None) for /live: the picture when something is in play, text otherwise."""
    now = now or datetime.now(timezone.utc)
    snap = snap if snap is not None else await lv_snapshot(gid, now, deep=True)
    embed, sig = await lv_live_embed(client, gid, scope, uid, private, now, snap=snap, until=until)
    try:
        data = await lv2_board_data(client, gid, scope, uid, private, now, snap)
    except Exception:
        log.warning("Live board data failed", exc_info=True)
        data = None
    if data is None:
        return embed, sig, None
    try:
        png = await asyncio.to_thread(locked_render, render_live_board, data)
    except Exception:
        log.warning("Live board render failed", exc_info=True)
        return embed, sig, None
    lines = []
    for g in data["games"]:
        c = lv_counts(g["rows"])
        bits = " · ".join(f"{LV_ICON[k]} {c[k]}" for k in ("cleared", "close", "live", "ahead", "behind", "dead") if c.get(k))
        sc = lambda t: f" {t['score']:g}" if t.get("score") is not None else ""
        lines.append(f"**{lv_abbr(g['away'])}{sc(g['away'])} · {lv_abbr(g['home'])}{sc(g['home'])}** · {clip(g['status'], 24)} · "
                     f"{len(g['rows'])} leg{'s' if len(g['rows']) != 1 else ''}" + (f" · {bits}" if bits else ""))
    if data["tonight"]:
        lines.append("⏰ Later: " + " · ".join(f"{t} {name}" for t, name, _ in data["tonight"]))
    embed.description = clip("\n".join(lines), 4000)
    f, name = await lv2_animated(png, "live")
    embed.set_image(url=f"attachment://{name}")
    return embed, sig, f


# ---- /gamecard: the game tracker card for any game, on demand ------------------------------------------------

def lv2_card_games(gid: int, snap: list[dict], now: datetime, uid: int) -> list[dict]:
    """Games the group has legs on: live first, then later today, then tonight's finals."""
    vis = [s for s in snap if s["public"]]         # the card is posted in the channel: hidden slips stay out
    games = list(lv_games_of(vis).values())
    start_of = lambda g: event_time(g["ev"]) or now
    _, end = lv_night_bounds(lv_night(now))
    keep = [g for g in games if g["ev"].get("state") == "in"
            or (g["ev"].get("state") == "pre" and start_of(g) <= end + timedelta(hours=12))
            or ((g["ev"].get("final") or g["ev"].get("state") == "post") and start_of(g) >= now - timedelta(hours=14))]
    order = {"in": 0, "pre": 1, "post": 2}
    keep.sort(key=lambda g: (order.get("post" if g["ev"].get("final") else g["ev"].get("state"), 3), start_of(g)))
    return keep


def lv2_game_label(g: dict) -> str:
    ev = g["ev"]
    n = len(g["rows"])
    state = "Final" if (ev.get("final") or ev.get("state") == "post") else (
        "LIVE " + (ev.get("detail") or "") if ev.get("state") == "in" else lv_status_text(ev))
    return clip(f"{lv_score_line(ev)} · {state} · {n} leg{'s' if n != 1 else ''}", 100)


async def gamecard_autocomplete(interaction: discord.Interaction, current: str) -> list:
    try:
        now = datetime.now(timezone.utc)
        snap = await asyncio.wait_for(lv_snapshot(interaction.guild_id, now), 2.5)
        games = lv2_card_games(interaction.guild_id, snap, now, interaction.user.id)
    except Exception:
        return []
    cur = (current or "").lower()
    out = []
    for g in games:
        label = lv2_game_label(g)
        if cur and cur not in label.lower():
            continue
        out.append(app_commands.Choice(name=label, value=str(g["id"])[:100]))
    return out[:25]


async def gamecard_payload(client, gid: int, uid: int, game: Optional[str], now: Optional[datetime] = None):
    """(embed, file) for one game's card, or (message, None) when there's no such game."""
    now = now or datetime.now(timezone.utc)
    snap = await lv_snapshot(gid, now, deep=True)
    games = lv2_card_games(gid, snap, now, uid)
    if not games:
        return ("No games with the group's legs on them right now or later today. Log a slip and its games show up "
                "here."), None
    g = None
    if game:
        g = next((x for x in games if str(x["id"]) == str(game)), None)
        if g is None:
            q = game.lower()
            g = next((x for x in games if q in lv2_game_label(x).lower()), None)
        if g is None:
            return "I couldn't find that game. Start typing a team and pick it from the list.", None
    else:
        g = games[0]                         # the live game first, else the next one up
    rows = lv2_game_rows(g)
    final = bool(g["ev"].get("final") or g["ev"].get("state") == "post")
    embed, f = await lv_card_payload(client, gid, g["ev"], g["path"], rows, final, now)
    return embed, f


