    v = discord.ui.View(timeout=900)
    keys = [("home", "🏠 Home")] + [(k, n) for k, n, _ in HELP_CATS]
    for i, (k, n) in enumerate(keys):
        v.add_item(HelpTopicButton(k, n, k == current, i // 4))
