R45_MOVED = ('receipts', 'recapchannel', 'todaypost', 'backups', 'settings', 'hotroles', 'halloffame', 'guide')


def r45_move_into(group, names) -> list[str]:
    moved = []
    for n in names:
        try:
            c = bot.tree.get_command(n)
        except Exception:
            c = None
        if c is None:
            continue
        bot.tree.remove_command(n)
        group.add_command(c)
        moved.append(n)
    return moved


