@sec_staff_only
async def staff_nickname_cmd(interaction: discord.Interaction, nickname: app_commands.Range[str, 2, 30],
                             player: Optional[app_commands.Range[str, 3, 60]] = None):
    if not player:
        key = norm_name(nickname)
        had = get_setting(0, f"nick:{key}")
