    await audit(interaction.client, interaction.guild_id, f"{interaction.user.display_name} taught the nickname {a} → {b}")
    await interaction.response.send_message(f"👍 **{a}** now means **{b.title()}** in slips, research and lookups.",
                                            ephemeral=True)



